// static ELF64 x86-64 programs, built from assembly with `gcc -nostdlib -static -Wl,-Ttext-segment=0x400000`:
//   hello: write(1, "hello from ring 3\n"); p = mmap(anonymous, 8 KiB); store and load through p; exit(getpid() + 6)  (99 if the memory test fails)
//   fault: stores to the unmapped address 0x1234
//   spin: counts down 200 million, then exit(5): the timer interrupts it many times in ring 3
//   win: a PE32+ program (`x86_64-w64-mingw32-gcc -nostdlib`) that calls the NT services directly: NtWriteFile, NtAllocateVirtualMemory (and uses the memory),
//        NtTerminateProcess(42)
